#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=12

REPO_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
cd "$REPO_DIR"
GH_REPO=gimanainidit/website_triad_proteksiber
DEPLOY_DIR=/opt/triad
DOMAIN=eranusasiber.my.id
LOCAL_ENV="$REPO_DIR/backend/.env"
BASELINE=$(mktemp)
ROOT_ENV_TMP=""
trap 'rm -f "$BASELINE" "$ROOT_ENV_TMP"' EXIT

as_triad() { sudo -u triad -H bash -c "cd $DEPLOY_DIR && $1"; }
compose() { as_triad "docker compose --env-file production.env $1"; }
api() { curl -fsS "https://api.github.com/repos/$GH_REPO$1"; }
json() { python3 -c "import json,sys; d=json.load(sys.stdin); print($1)"; }
local_value() { sed -n "s/^$1=//p" "$LOCAL_ENV" 2>/dev/null | tail -n1; }
status_of() { curl -s -o /dev/null -m 15 -w '%{http_code}' "$@" || true; }
other_sites() {
  printf 'duckdns-media %s\n' "$(status_of https://gadgetagent-triad.duckdns.org/)"
  printf 'ctf-80 %s\n' "$(status_of -H 'Host: ctf.eranusasiber.my.id' http://127.0.0.1/)"
  printf 'ctf-8080 %s\n' "$(status_of -H 'Host: ctf.eranusasiber.my.id' http://127.0.0.1:8080/)"
}
# Edit a root-owned env file through a private copy, then install it back.
# shellcheck disable=SC2024  # the redirect target is our own temp file
open_root_env() { ROOT_ENV_TMP=$(mktemp); ENV_FILE=$ROOT_ENV_TMP; sudo cat "$1" > "$ENV_FILE"; }
close_root_env() {
  sudo install -m 600 -o triad -g triad "$ENV_FILE" "$1"
  rm -f "$ROOT_ENV_TMP"; ROOT_ENV_TMP=""; ENV_FILE="$DEPLOY_DIR/*.env"
}
# Compose env files cannot hold a single quote inside a quoted value.
ask_env_secret() {
  while :; do
    ask_secret "$1" "$2"
    if [[ "${!1}" == *"'"* ]]; then warn "Nilai tidak boleh mengandung tanda kutip '. URL-encode password (%27)."
    elif [[ "${!1}" == *:PASSWORD@* ]]; then warn "Masih placeholder PASSWORD; isi URL asli."
    else return 0; fi
  done
}

banner "TRIAD deploy ke VPS bersama ($DOMAIN)"

stage "Revoke key legacy (T04)"
say "Dua key lama pernah ter-commit dan harus dimatikan di layanannya."
open_url "https://app.emergent.sh"
step "Emergent: buka pengaturan API/Universal key, revoke key yang diawali sk-emergent-."
open_url "https://labibeduph-triad-proteksiber-webflow2.hf.space"
step "n8n hf.space: Settings → n8n API → hapus API key yang ada."
note "Kalau space n8n sudah mati, cukup hapus space-nya di Hugging Face."
pause "Enter kalau keduanya sudah dicabut."

stage "Cabut akses Emergent/Lovable di GitHub (T11)"
open_url "https://github.com/settings/installations"
step "Installed GitHub Apps: Configure → Uninstall untuk Emergent dan Lovable."
open_url "https://github.com/settings/applications"
step "Authorized OAuth Apps: Revoke untuk Emergent dan Lovable / GPT Engineer."
open_url "https://github.com/$GH_REPO/settings/hooks"
step "Webhooks, lalu Deploy keys dan Collaborators di menu kiri: hapus entri Emergent/Lovable."
pause "Enter kalau sudah bersih."

stage "Push riwayat bersih (T10)"
SHA=$(git rev-parse main)
PUSHED_SHA=""
say "main lokal: $(git log -1 --format='%h %s' main)"
git remote get-url origin >/dev/null 2>&1 || git remote add origin "https://github.com/$GH_REPO.git"
if [[ "$(api "/branches/main" | json 'd["commit"]["sha"]' || true)" == "$SHA" ]]; then
  PUSHED_SHA=$SHA
  note "GitHub main sudah sama dengan lokal; lewati push."
else
  open_url "https://github.com/settings/personal-access-tokens/new"
  step "Buat fine-grained token: hanya repo $GH_REPO, Contents = Read and write, kedaluwarsa 1 hari."
  ask_secret GITHUB_PUSH_TOKEN "Tempel token (tidak disimpan):"
  warn "Force push menimpa riwayat main di GitHub dengan riwayat yang sudah dibersihkan."
  if confirm "Force push main dan tag legacy/emergent-2026-10-11 sekarang?"; then
    askpass=$(mktemp); chmod 700 "$askpass"
    printf '#!/bin/sh\ncase "$1" in Username*) echo x-access-token;; *) printf "%%s\\n" "$GITHUB_PUSH_TOKEN";; esac\n' > "$askpass"
    GIT_ASKPASS="$askpass" GITHUB_PUSH_TOKEN="$GITHUB_PUSH_TOKEN" GIT_TERMINAL_PROMPT=0 \
      git push --force origin main refs/tags/legacy/emergent-2026-10-11
    rm -f "$askpass"
    PUSHED_SHA=$SHA
  else
    SKIPPED+=("push riwayat bersih (T10)")
  fi
fi

stage "Default branch main, hapus branch legacy (T10)"
open_url "https://github.com/$GH_REPO/settings"
step "Default branch: klik ikon ⇄, pilih main, Update, lalu konfirmasi."
until [[ "$(api "" | json 'd["default_branch"]' || true)" == main ]]; do
  pause "Default branch belum main menurut API GitHub. Enter untuk cek lagi."
done
remaining=$(api "/branches" | json '" ".join(b["name"] for b in d if b["name"] != "main")' || true)
if [[ -n "$remaining" ]] && confirm "Hapus branch remote: $remaining ?"; then
  open_url "https://github.com/$GH_REPO/branches"
  step "Hapus branch tersebut lewat ikon tempat sampah (atau git push origin --delete ...)."
  pause "Enter kalau sudah."
fi

stage "Tunggu CI dan image (T12)"
SHA=${PUSHED_SHA:-$(git rev-parse main)}
say "Menunggu workflow 'Build and deploy VPS' untuk ${SHA:0:7}."
open_url "https://github.com/$GH_REPO/actions"
while :; do
  run=$(api "/actions/runs?head_sha=$SHA&event=push&per_page=1" \
        | json '(d["workflow_runs"] or [{}])[0].get("status","none")+" "+str((d["workflow_runs"] or [{}])[0].get("conclusion"))') \
    || run="api-error (coba lagi)"
  note "status: $run"
  case "$run" in
    "completed success") break ;;
    completed*) warn "CI gagal. Perbaiki dulu (lihat tab Actions), push, lalu jalankan ulang wizard."; exit 1 ;;
  esac
  sleep 30
done
FRONTEND_IMAGE="ghcr.io/$GH_REPO-frontend:$SHA"
BACKEND_IMAGE="ghcr.io/$GH_REPO-backend:$SHA"

stage "DNS di Cloudflare (T14)"
open_url "https://dash.cloudflare.com"
step "Pilih zona $DOMAIN → DNS → Records."
step "Add record: Type A, Name @, IPv4 67.217.244.248."
step "Add record: Type CNAME, Name www, Target $DOMAIN."
note "Pakai DNS only (awan abu-abu): proxy Cloudflare memutus request > 100 s, padahal fitur AI bisa lebih lama."
note "Jangan tambah AAAA."
until getent ahosts "$DOMAIN" >/dev/null && getent ahosts "www.$DOMAIN" >/dev/null; do
  pause "Belum resolve. Enter untuk cek lagi (propagasi biasanya < 5 menit)."
done
say "$DOMAIN → $(getent ahosts "$DOMAIN" | awk '{print $1}' | sort -u | tr '\n' ' ')"

stage "Siapkan host (T15)"
other_sites | tee "$BASELINE" | while read -r name code; do note "sebelum deploy: $name → $code"; done
say "setup-host.sh membuat user triad, /opt/triad, dan site nginx untuk $DOMAIN."
say "Situs lain tidak disentuh; site TRIAD dicabut lagi kalau nginx -t gagal."
if confirm "Jalankan sudo bash deploy/shared-host/setup-host.sh?"; then
  sudo bash deploy/shared-host/setup-host.sh
else
  warn "Tahap berikutnya butuh /opt/triad. Berhenti di sini."; exit 1
fi

stage "Isi backend.env dan production.env (T16)"
open_root_env "$DEPLOY_DIR/backend.env"
for key in DATABASE_URL SUPABASE_URL SUPABASE_SERVICE_KEY; do
  current=$(_existing "$key" || true)
  if [[ -z "$current" || "$current" == *:PASSWORD@* ]] && [[ -n "$(local_value "$key")" ]]; then
    write_env "$key" "$(local_value "$key")"
  fi
done
ask_env_secret DATABASE_URL "DATABASE_URL (Enter = pakai yang ada):"
write_env DATABASE_URL "$DATABASE_URL"
ask_env_secret SUPABASE_SERVICE_KEY "SUPABASE_SERVICE_KEY (Enter = pakai yang ada):"
write_env SUPABASE_SERVICE_KEY "$SUPABASE_SERVICE_KEY"
[[ -n "$(_existing JWT_SECRET_KEY || true)" ]] || write_env JWT_SECRET_KEY "$(openssl rand -hex 48)"
close_root_env "$DEPLOY_DIR/backend.env"
open_root_env "$DEPLOY_DIR/production.env"
write_env SITE_ADDRESS ":80"
write_env FRONTEND_IMAGE "$FRONTEND_IMAGE"
write_env BACKEND_IMAGE "$BACKEND_IMAGE"
close_root_env "$DEPLOY_DIR/production.env"

stage "Tarik image, buat tabel, jalankan stack (T16)"
if ! compose "pull frontend backend"; then
  open_url "https://github.com/settings/tokens/new?scopes=read:packages&description=triad-vps-ghcr"
  step "Image GHCR private. Buat classic token dengan scope read:packages saja."
  ask_secret GHCR_TOKEN "Tempel token (disimpan docker untuk user triad):"
  printf '%s' "$GHCR_TOKEN" | sudo -u triad -H docker login ghcr.io -u gimanainidit --password-stdin
  compose "pull frontend backend"
fi
say "init_db.py hanya membuat tabel CMS yang belum ada (users, templates, ...); tabel lain tidak diubah."
if confirm "Jalankan init_db.py lalu start stack?"; then
  compose "run --rm --no-deps backend python init_db.py"
  compose "up -d --wait --wait-timeout 180"
  as_triad "curl -fsS http://127.0.0.1:8180/api/health" && printf '\n'
  ss -ltnH 'sport = :8180' | awk '{print "  listener: " $4}'
else
  warn "Stack belum jalan. Berhenti di sini."; exit 1
fi

stage "Akun superadmin (T16)"
while :; do
  ask ADMIN_EMAIL "Email admin:"
  [[ "$ADMIN_EMAIL" =~ ^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]+$ ]] && break
  warn "Format email tidak valid."
done
ask_secret ADMIN_PASSWORD "Password admin (min. 12 karakter, tidak disimpan):"
printf '%s\n' "$ADMIN_PASSWORD" | compose "run --rm -T --no-deps backend python create_admin.py $(printf %q "$ADMIN_EMAIL")"

stage "HTTPS (T17)"
say "certbot menambahkan blok 443 ke site triad saja."
if confirm "Jalankan sudo certbot --nginx untuk $DOMAIN dan www.$DOMAIN?"; then
  sudo certbot --nginx --keep-until-expiring --redirect -d "$DOMAIN" -d "www.$DOMAIN"
  note "Kalau nanti DNS di-proxy Cloudflare: SSL/TLS → Overview → Full (strict)."
else
  SKIPPED+=("certbot HTTPS (T17)")
fi

stage "Cek akhir"
code=$(status_of "https://$DOMAIN/api/health")
say "https://$DOMAIN/api/health → $code"
while read -r name after; do
  before=$(awk -v n="$name" '$1 == n {print $2}' "$BASELINE")
  if [[ "$before" == "$after" ]]; then note "$name: $after (sama seperti sebelum deploy)"
  else warn "$name: sebelum $before, sesudah $after"; SKIPPED+=("cek $name"); fi
done < <(other_sites)
[[ "$code" == 200 ]] || SKIPPED+=("health HTTPS masih $code")
note "Lanjutkan T18 di browser: login admin, upload PDF, upload template."

finish
}

run_wizard "$@"; exit
